"""Exam question on the topology generated by a basis on a finite set: counting open sets, interior, closure, boundary.

The stem gives X = {1, ..., n}, a collection B of subsets that is a basis (it contains the smallest open
neighbourhood of every point, plus a few unions of them), and a subset A. Four parts:

(a) the number of open sets of the topology T generated by B                    number (whole), 2 marks
(b) the number of points in the interior of A                                    number (whole), 1 mark
(c) the number of points in the closure of A                                     number (whole), 1 mark
(d) the number of points in the boundary of A, |closure| - |interior|           number (whole), 2 marks, follow_through part_c - part_b

Construction: a random preorder on X (points grouped into blocks, blocks ordered by a random acyclic relation, then
closed under transitivity) gives each point p a smallest open neighbourhood U_p, the set of points below p. The
topology is the family of up-closed sets (S is open exactly when p in S implies U_p inside S). B is every distinct U_p
together with one or two further open sets that are unions of them, so B really is a basis and is not minimal.

Every key is found two ways: by taking all unions of members of B and counting the distinct ones, and by testing every
subset of X for the neighbourhood condition. The interior is the union of the members of B inside A and the closure is
the set of points every one of whose basic neighbourhoods meets A; each is checked against the complement relation
cl(A) = X minus int(X minus A).
"""

from __future__ import annotations

import random
from itertools import chain, combinations

from ..core import attempts, check, generator, phrase
from .exd_x_r2h_support import build_part

_SIZES = (6, 7, 8)

_STEM = (
    "The universe is X = {{{universe}}}. The collection B = {{{names}}} is a basis for a topology T on X, where "
    "{sets}. Let A = {a_set}.",
    "Let X = {{{universe}}}. A topology T on X has basis B = {{{names}}}, with {sets}. Consider the subset "
    "A = {a_set} of X.",
    "A basis B = {{{names}}} for a topology T on the set X = {{{universe}}} is given by {sets}. Let A = {a_set}.",
)
_PROMPT_A = (
    "Find the number of open sets of T (including the empty set and X).",
    "How many open sets does T have, counting the empty set and X?",
)
_PROMPT_B = (
    "Find the number of points in the interior of A.",
    "How many points does the interior of A contain?",
)
_PROMPT_C = (
    "Find the number of points in the closure of A.",
    "How many points does the closure of A contain?",
)
_PROMPT_D = (
    "Hence find the number of points in the boundary of A.",
    "Use your interior and closure to find how many points lie in the boundary of A.",
)


def _subsets(items):
    items = list(items)
    return chain.from_iterable(combinations(items, k) for k in range(len(items) + 1))


def _fmt(s) -> str:
    return "{" + ", ".join(str(i) for i in sorted(s)) + "}"


def _neighbourhoods(rng: random.Random, n: int) -> dict:
    """Smallest open neighbourhoods U_p of a random preorder: blocks of equivalent points, blocks ordered by a
    random relation made transitive."""
    points = list(range(1, n + 1))
    rng.shuffle(points)
    cuts = sorted(rng.sample(range(1, n), rng.randint(2, min(5, n - 1))))
    blocks = [points[i:j] for i, j in zip([0, *cuts], [*cuts, n])]
    k = len(blocks)
    below = [{i} for i in range(k)]  # below[j]: blocks i with i <= j in the order
    for j in range(k):
        for i in range(j):
            if rng.random() < 0.4:
                below[j].add(i)
    for j in range(k):  # transitive closure, processing blocks in index order
        for i in sorted(below[j]):
            below[j] |= below[i]
    nbhd = {}
    for j, block in enumerate(blocks):
        reach = frozenset(p for i in below[j] for p in blocks[i])
        for p in block:
            nbhd[p] = reach
    return nbhd


def _build(rng: random.Random) -> dict:
    n = rng.choice(_SIZES)
    universe = frozenset(range(1, n + 1))
    for _ in attempts(3000, "a basis whose topology has a non-trivial interior, closure and boundary"):
        nbhd = _neighbourhoods(rng, n)
        minimal = sorted({s for s in nbhd.values()}, key=lambda s: (len(s), sorted(s)))
        if not 4 <= len(minimal) <= 7:
            continue
        unions = {a | b for a, b in combinations(minimal, 2)} - set(minimal)
        extra = rng.sample(sorted(unions, key=lambda s: (len(s), sorted(s))), min(len(unions), rng.randint(1, 2)))
        basis = sorted([*minimal, *extra], key=lambda s: (len(s), sorted(s)))
        a_set = frozenset(rng.sample(sorted(universe), rng.randint(2, n - 3)))
        interior = frozenset(p for p in universe if nbhd[p] <= a_set)
        closure = frozenset(p for p in universe if nbhd[p] & a_set)
        if not (interior != a_set and closure != a_set and interior and len(closure - interior) >= 1):
            continue
        spread = {len(a_set), len(closure), len(interior) + 1, len(interior) - 1, len(a_set) - 1, len(closure) - 1}
        if len({v for v in spread if v >= 1 and v != len(interior)}) >= 4:
            break

    # Route 1: all unions of members of B. Route 2: every subset tested against the neighbourhood condition.
    opens_by_unions = {frozenset().union(*combo) for combo in _subsets(basis)}
    opens_by_test = {frozenset(s) for s in _subsets(universe) if all(nbhd[p] <= frozenset(s) for p in s)}
    check(opens_by_unions == opens_by_test, "the two counts of open sets disagree")
    open_count = len(opens_by_unions)
    # Interior and closure from the basis, and the duality cl(A) = X - int(X - A).
    int_from_basis = frozenset().union(*[b for b in basis if b <= a_set])
    complement = universe - a_set
    int_complement = frozenset().union(*[b for b in basis if b <= complement])
    check(int_from_basis == interior, "interior disagrees with the basis route")
    check(universe - int_complement == closure, "closure disagrees with the duality")
    n_int, n_cl = len(interior), len(closure)
    boundary = closure - interior
    check(len(boundary) == n_cl - n_int and interior <= a_set <= closure, "interior, set and closure are not nested")

    meet = frozenset().union(*[b for b in basis if b & a_set])
    a_wrong = [
        (len(basis), "counts-basis-as-topology"),
        (2 ** len(minimal), "counts-unions-without-collapse"),
        (2**n, "takes-discrete-topology"),
        (open_count - 1, "forgets-the-empty-set"),
        (len(basis) + 1, "counts-basis-as-topology"),
        (open_count + 1, "forgets-the-empty-set"),
        (open_count + 2, "counts-unions-without-collapse"),
    ]
    b_wrong = [
        (len(a_set), "treats-set-as-open"),
        (n_cl, "interior-closure-confused"),
        (sum(1 for b in basis if b <= a_set), "counts-basis-members-not-points"),
        (n_int + 1, "off-by-one-count"),
        (n_int - 1, "off-by-one-count"),
        (len(a_set) - 1, "treats-set-as-open"),
        (n_cl - 1, "interior-closure-confused"),
    ]
    c_wrong = [
        (len(a_set), "treats-set-as-closed"),
        (n_int, "interior-closure-confused"),
        (len(meet), "closure-as-union-of-meeting-members"),
        (n - n_int, "closure-as-complement-of-interior"),
        (n_cl + 1, "off-by-one-count"),
    ]
    d_wrong = [
        (n_cl, "boundary-as-closure"),
        (n_cl + n_int, "boundary-adds-interior"),
        (len(a_set) - n_int, "boundary-inside-set-only"),
        (n_cl - len(a_set), "boundary-outside-set-only"),
        (n_cl - n_int + 1, "off-by-one-count"),
    ]
    # Counts of points cannot be negative or zero here.
    a_wrong, b_wrong, c_wrong, d_wrong = (
        [(v, t) for v, t in w if v >= 1] for w in (a_wrong, b_wrong, c_wrong, d_wrong)
    )
    names = [f"B{i}" for i in range(1, len(basis) + 1)]
    sets_text = "; ".join(f"{nm} = {_fmt(s)}" for nm, s in zip(names, basis))
    stem = phrase(
        rng,
        _STEM,
        universe=", ".join(str(i) for i in sorted(universe)),
        names=", ".join(names),
        sets=sets_text,
        a_set=_fmt(a_set),
    )
    parts = [
        build_part(
            phrase(rng, _PROMPT_A),
            open_count,
            kind="number",
            marks=2,
            working=[
                "The open sets are exactly the unions of members of B (the empty union is the empty set).",
                f"Listing the distinct unions gives {open_count} open sets.",
            ],
            wrong=a_wrong,
        ),
        build_part(
            phrase(rng, _PROMPT_B),
            n_int,
            kind="number",
            marks=1,
            working=[f"The interior of A is the union of the members of B inside A: {_fmt(interior)}, {n_int} points."],
            wrong=b_wrong,
        ),
        build_part(
            phrase(rng, _PROMPT_C),
            n_cl,
            kind="number",
            marks=1,
            working=[
                "A point is in the closure of A exactly when every basic neighbourhood of it meets A.",
                f"The closure is {_fmt(closure)}, {n_cl} points.",
            ],
            wrong=c_wrong,
        ),
        build_part(
            phrase(rng, _PROMPT_D),
            n_cl - n_int,
            kind="number",
            marks=2,
            working=[f"The boundary is the closure minus the interior: {n_cl} - {n_int} = {n_cl - n_int} points."],
            wrong=d_wrong,
            follow_through="part_c - part_b",
        ),
    ]
    return dict(text=stem, latex=f"plain:{stem}", parts=parts)


@generator("exd_x_r2h_finite_topology_chain", level=19, presets={"exam": dict(tier="exam")})
def exd_x_r2h_finite_topology_chain(rng: random.Random, tier: str = "exam") -> dict:
    """Open sets of a topology given by a basis, then interior, closure and boundary of a subset."""
    check(tier == "exam", "exd_x_r2h_finite_topology_chain: only the exam tier exists")
    return _build(rng)
